mapper.select:
SELECT num, title, content, author, id, postdate, visitcount
FROM board
WHERE num = #{num}

mapper.update:
UPDATE board
SET visitcount = visitcount + 1
WHERE num = #{num}

UPDATE board
SET title = #{title}, content = #{content}
WHERE num = #{num}

mapper.select:
SELECT num, title, content, author, id, postdate, visitcount FROM board
WHERE ${searchField} LIKE CONCAT('%', #{searchWord}, '%')
ORDER BY num DESC LIMIT #{offset} , #{pageSize}
